)
$written = 0
foreach ($item in $payload) {
    $target = Join-Path $Destination $item.Path
    if ((Test-Path -LiteralPath $target) -and -not $Force) { Write-Warning "Exists, skipped (use -Force to overwrite): $target"; continue }
    $dir = Split-Path -Parent $target
    if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
    $bytes = [Convert]::FromBase64String(($item.Data -replace '\s', ''))
    $sha = [Security.Cryptography.SHA256]::Create()
    $hash = ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '')
    if ($hash -ne $item.Sha256) { throw "Checksum mismatch for $($item.Path). The installer file is damaged; copy it again." }
    [IO.File]::WriteAllBytes($target, $bytes)
    $written++
    Write-Host "  wrote $($item.Path)"
}
Write-Host "Installed $written of $($payload.Count) files under $Destination"
